    static {
        items.put(68, "Hełm");
        items.put(2170, "Zbroja Skórzana");
        items.put(1, "Hełm");
        items.put(2, "Tarcza");
        items.put(3, "Topór");
        items.put(4, "Łuk");
        items.put(5, "Kostur");
