args.old_string:
package com.example.d1editor;

import java.util.HashMap;
import java.util.Map;

public class ItemDatabase {
    private static final Map<Integer, String> items = new HashMap<>();

    static {
        items.put(68, "Hełm");
        items.put(2170, "Zbroja Skórzana");
        items.put(1, "Hełm");
        items.put(2, "Tarcza");
        items.put(3, "Topór");
        items.put(4, "Łuk");
        items.put(5, "Kostur");
        items.put(6, "Pierścień");
        items.put(7, "Amulet");
        items.put(8, "Mikstura");
        // Added items
        items.put(21, "Mikstura Many");
        items.put(22, "Mikstura Lecznicza");
        items.put(30, "Mikstura Lecznicza");
        items.put(31, "Mikstura Many");
        items.put(34, "Zwój Teleportacji");
        items.put(35, "Zwój Identyfikacji");
        items.put(101, "Zwój Town Portal");
        items.put(103, "Zwój Identify");
        items.put(152, "Miecz Krótki");
        items.put(65535, "Puste");
    }

    public static String getItemName(int idx) {
        return items.getOrDefault(idx, "Nieznany przedmiot (" + idx + ")");
    }

    public static int getItemId(String name) {
        if (name == null || name.isEmpty()) return 65535;
        for (Map.Entry<Integer, String> entry : items.entrySet()) {
            if (entry.getValue().equalsIgnoreCase(name)) {
                return entry.getKey();
            }
        }
        return 65535;
    }
}

