        items.put(7, "Amulet");

        // Potions & Elixirs
        items.put(8, "Mikstura");
        items.put(21, "Mikstura Many");
        items.put(22, "Mikstura Lecznicza");
        items.put(30, "Duża Mikstura Lecznicza");
        items.put(31, "Duża Mikstura Many");
        items.put(32, "Pojemnik Ożywienia");
        items.put(40, "Eliksir Siły");
        items.put(41, "Eliksir Zręczności");
        items.put(42, "Eliksir Magii");
        items.put(43, "Eliksir Witalności");

        // Scrolls
        items.put(34, "Zwój Teleportacji");
        items.put(35, "Zwój Identyfikacji");
        items.put(101, "Zwój Town Portal");
        items.put(102, "Zwój Kuli Ognia");
        items.put(103, "Zwój Identify");
        items.put(104, "Zwój Błyskawicy");
        items.put(105, "Zwój Leczenia");
        items.put(106, "Zwój Apokalipsy");
        items.put(107, "Zwój Ściany Ognia");

        // Unique / Quest / Misc Items
        items.put(200, "Maska Arreat");
        items.put(201, "Pierścień Jordana");
        items.put(202, "Harlequin Crest");
        items.put(203, "Arkaine's Valor");
        items.put(204, "Rzeźnik (The Butcher's Cleaver)");
        items.put(205, "Ostrze Griswolda");
        items.put(206, "Stalowa Zasłona");
        items.put(207, "Czapka Myśliciela");
        items.put(1000, "Sakiewka Złota");

        // Empty slot
        items.put(65535, "Puste");
    }

    public static String getItemName(int idx) {
        return items.getOrDefault(idx, "Nieznany przedmiot (" + idx + ")");
    }

    public static int getItemId(String name) {
        if (name == null || name.trim().isEmpty()) return 65535;
        for (Map.Entry<Integer, String> entry : items.entrySet()) {
            if (entry.getValue().equalsIgnoreCase(name.trim())) {
                return entry.getKey();
            }
        }
        return 65535;
    }

    public static List<String> getAllItemNames() {
        List<String> list = new ArrayList<>();
        for (Map.Entry<Integer, String> entry : items.entrySet()) {
            if (entry.getKey() != 65535) {
                list.add(entry.getValue());
            }
        }
        return list;
    }

    public static String getRandomItemName() {
        List<String> validItems = getAllItemNames();
        if (validItems.isEmpty()) return "Puste";
        return validItems.get(random.nextInt(validItems.size()));
    }
}

